mapper.select:
SELECT user_id, username, password_hash, nickname, role, status, token_version,
       failed_login_attempts, locked_until, create_time
FROM t_user WHERE username=#{username}

mapper.insert:
INSERT INTO sys_user_role (user_id, role_id)
SELECT u.user_id, r.role_id FROM t_user u JOIN sys_role r ON r.role_code='VIEWER'
WHERE u.username=#{username}

mapper.update:
UPDATE t_user
SET failed_login_attempts=failed_login_attempts+1,
    locked_until=CASE WHEN failed_login_attempts >= #{maxAttempts}
      THEN #{lockedUntil} ELSE locked_until END
WHERE user_id=#{userId}
